param([string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework;Add-Type -AssemblyName System.Runtime.Serialization
function Assert([bool]$condition,[string]$message){if(-not$condition){throw $message}}
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
$exe=Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe';$assembly=[Reflection.Assembly]::LoadFrom($exe)
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$variableType=$assembly.GetType('HalconWinFormsDemo.Models.VmGlobalVariableData',$true);$parametersType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolParameterData',$true);$recipeType=$assembly.GetType('HalconWinFormsDemo.Models.VisionRecipe',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s59-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
$app=[Windows.Application]::Current;$ownsApp=$null-eq$app;if($ownsApp){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.ShowInTaskbar=$false;$window.Left=-10000;$window.Show();Pump 150
function F([string]$name){$field=$mainType.GetField($name,$all);if($null-eq$field){return $null};$value=$field.GetValue($window);Write-Output -NoEnumerate $value}
function M([string]$name,[object[]]$parameters=@()){try{$mainType.GetMethod($name,$private).Invoke($window,$parameters)}catch{throw ($name+': '+$_.Exception.Message)}}
function Kind([string]$name){[Enum]::Parse($kindType,$name)}
function Tool([string]$kind,[string]$name){M 'CreateFlowTool' ([object[]]@((Kind $kind),$name,$true,$null))}
function NewVar([string]$name,[string]$type,[object]$default,[object]$current){$v=[Activator]::CreateInstance($variableType);$v.Name=$name;$v.ValueType=$type;if($type-eq'Number'){$v.DefaultNumberValue=[double]$default}elseif($type-eq'String'){$v.DefaultTextValue=[string]$default}elseif($type-eq'Boolean'){$v.DefaultBooleanValue=[bool]$default}else{$v.DefaultResultCodeValue=[string]$default};$v.SetCurrentValue($current);$v}
function Out($tool,[string]$name){$args=[object[]]@($name,$null);Assert($tool.GetType().GetMethod('TryGetOutputValue').Invoke($tool,$args))('Missing output '+$name);$args[1]}
function Run($tool){M 'ExecuteFlowTool' ([object[]]@($tool,'S59 smoke'))}
function RunFailure($tool){try{Run $tool|Out-Null;throw 'Expected execution failure'}catch{$e=$_.Exception;while($e.InnerException){$e=$e.InnerException};return $e.Message}}
try{
  Assert((F 'GlobalVariableWorkspace').Visibility.ToString()-eq'Collapsed') 'Global variable workspace must not occupy the default first screen'
  M 'OpenGlobalVariablesButton_Click' ([object[]]@($null,$null))|Out-Null;Assert((F 'GlobalVariableWorkspace').Visibility.ToString()-eq'Visible'-and(F 'MainWorkspaceGrid').Visibility.ToString()-eq'Collapsed') 'On-demand variable workspace did not replace main workspace'
  M 'CloseGlobalVariablesButton_Click' ([object[]]@($null,$null))|Out-Null;Assert((F 'GlobalVariableWorkspace').Visibility.ToString()-eq'Collapsed'-and(F 'MainWorkspaceGrid').Visibility.ToString()-eq'Visible') 'Closing variable workspace did not restore main workspace'

  $globals=F 'globalVariables';$initial=$globals.Count;M 'NewGlobalVariableButton_Click' ([object[]]@($null,$null))|Out-Null;Assert($globals.Count-eq($initial+1)) 'Variable create failed';M 'UndoFlowEditButton_Click' ([object[]]@($null,$null))|Out-Null;Assert($globals.Count-eq$initial) 'Variable create undo failed';M 'RedoFlowEditButton_Click' ([object[]]@($null,$null))|Out-Null;Assert($globals.Count-eq($initial+1)) 'Variable create redo failed';$globals.Clear()
  $number=NewVar 'Threshold' 'Number' ([double]5) ([double]7);$text=NewVar 'LotName' 'String' 'LOT-A' 'LOT-B';$boolean=NewVar 'EnabledFlag' 'Boolean' $false $false;$result=NewVar 'StationResult' 'ResultCode' 'OK' 'NG';foreach($v in @($number,$text,$boolean,$result)){$globals.Add($v)};M 'RefreshGlobalVariableSubscriptions'|Out-Null
  Assert($number.VariableId.Length-gt0-and$number.CurrentValueText-eq'7') 'Stable ID or Number current value failed'
  try{$number.SetCurrentValue([double]::NaN);throw 'Expected nonfinite rejection'}catch{Assert($_.Exception.Message.Length-gt0) 'Nonfinite value error is unclear'}
  try{$result.SetCurrentValue('PASS');throw 'Expected result-code rejection'}catch{Assert($_.Exception.Message-match'OK.*NG') 'Invalid ResultCode error is unclear'}

  $flow=F 'flowTools';M 'DisposeFlowTools'|Out-Null;$flow.Clear()
  $source=Tool ImageSource 'Typed Source';$readNumber=Tool GlobalVariableRead 'Read Threshold';$writeNumber=Tool GlobalVariableWrite 'Write Threshold';$judge=Tool NumericJudge 'Threshold Judge';$script=Tool CSharpDllScript 'Variable Script';$readText=Tool GlobalVariableRead 'Read Lot';$assemblyText=Tool TextAssembly 'Lot Message';$boolSource=Tool TextParser 'Boolean Source';$writeBoolean=Tool GlobalVariableWrite 'Write Flag';$readResult=Tool GlobalVariableRead 'Read Result';$logic=Tool ResultLogicAggregation 'Result Pass';foreach($t in @($source,$readNumber,$writeNumber,$judge,$script,$readText,$assemblyText,$boolSource,$writeBoolean,$readResult,$logic)){$flow.Add($t)}
  $source.SetOutputValue('Width',[double]42);$source.ResultCode='OK';$boolSource.SetOutputValue('Matched',$true);$boolSource.ResultCode='OK'
  $readNumber.Parameters.GlobalVariableId=$number.VariableId;$writeNumber.Parameters.GlobalVariableId=$number.VariableId;$writeNumber.SetInputBinding('NumberValue',$source.ToolId,'Width')
  $judge.SetInputBinding('Value',$readNumber.ToolId,'NumberValue');$judge.InputToolId=$readNumber.ToolId;$judge.InputPortName='NumberValue';$judge.NumericLowerLimit=7;$judge.NumericUpperLimit=7
  $script.SetInputBinding('NumberA',$readNumber.ToolId,'NumberValue');$script.Parameters.ScriptInlineCode='return ScriptToolResult.Ok(input.NumberA + 1, "VAR");'
  $readText.Parameters.GlobalVariableId=$text.VariableId;$assemblyText.SetInputBinding('String',$readText.ToolId,'TextValue');$assemblyText.Parameters.TextAssemblyTemplate='LOT={String}'
  $writeBoolean.Parameters.GlobalVariableId=$boolean.VariableId;$writeBoolean.SetInputBinding('BooleanValue',$boolSource.ToolId,'Matched')
  $readResult.Parameters.GlobalVariableId=$result.VariableId;$logic.SetInputBinding('ResultCodeA',$readResult.ToolId,'ResultCodeValue');$logic.Parameters.ResultLogicOperation='PassThrough'
  Assert((Run $readNumber).ResultCode-eq'OK'-and[double](Out $readNumber NumberValue)-eq7) 'Number variable read failed';Assert((Run $judge).ResultCode-eq'OK') 'Number variable did not drive NumericJudge';Assert((Run $script).ResultCode-eq'OK'-and[double](Out $script Number)-eq8) 'Number variable did not drive script'
  Assert((Run $writeNumber).ResultCode-eq'OK'-and[double]$number.NumberValue-eq42-and[bool](Out $writeNumber Changed)) 'Number variable write/Changed failed';Run $readNumber|Out-Null;Assert([double](Out $readNumber NumberValue)-eq42) 'Read-after-write value failed'
  Assert((Run $readText).ResultCode-eq'OK') 'String variable read failed';Assert((Run $assemblyText).ResultCode-eq'OK'-and(Out $assemblyText Text)-eq'LOT=LOT-B') 'String variable did not drive TextAssembly'
  Assert((Run $writeBoolean).ResultCode-eq'OK'-and$boolean.BooleanValue) 'Boolean variable write failed'
  Assert((Run $readResult).ResultCode-eq'OK') 'ResultCode variable read failed';Assert((Run $logic).ResultCode-eq'NG') 'ResultCode variable did not drive result logic'

  $bad=Tool GlobalVariableWrite 'Bad Type';$bad.Parameters.GlobalVariableId=$number.VariableId;$bad.SetInputBinding('TextValue',$readText.ToolId,'TextValue');$flow.Add($bad);Assert((RunFailure $bad)-match'NumberValue') 'Type mismatch was not rejected clearly'
  $badReadConsumer=Tool NumericJudge 'Bad Read Port';$badReadConsumer.SetInputBinding('Value',$readText.ToolId,'NumberValue');$flow.Add($badReadConsumer);$badReadBinding=$badReadConsumer.GetInputBinding('Value');$badReadError=M 'GetInputBindingConfigurationError' ([object[]]@($badReadConsumer,$badReadBinding));Assert($badReadError-match'NumberValue') 'Inactive typed read port was not rejected during connection validation'
  $missing=Tool GlobalVariableWrite 'Missing Upstream';$missing.Parameters.GlobalVariableId=$number.VariableId;$missing.SetInputBinding('NumberValue',$source.ToolId,'Height');$flow.Add($missing);Assert((RunFailure $missing).Length-gt0) 'Upstream-not-run/missing-value error failed'
  $late=Tool ImageSource 'Late Source';$flow.Add($late);$writeNumber.SetInputBinding('NumberValue',$late.ToolId,'Width');$binding=$writeNumber.GetInputBinding('NumberValue');$orderError=M 'GetInputBindingConfigurationError' ([object[]]@($writeNumber,$binding));Assert($orderError.Length-gt0) 'Deterministic order protection failed';$writeNumber.SetInputBinding('NumberValue',$source.ToolId,'Width')

  M 'RefreshGlobalVariableSubscriptions'|Out-Null;(F 'GlobalVariableListBox').SelectedItem=$number;M 'DeleteGlobalVariableButton_Click' ([object[]]@($null,$null))|Out-Null;Assert($globals.Contains($number)-and((F 'GlobalVariableValidationText').Text.Length-gt0)) 'Subscribed variable deletion protection failed'
  $readPorts=$metadataType.GetMethod('GetOutputPorts',[Reflection.BindingFlags]'Static,Public').Invoke($null,[object[]]@((Kind GlobalVariableRead)));$writePorts=$metadataType.GetMethod('GetInputPorts',[Reflection.BindingFlags]'Static,Public').Invoke($null,[object[]]@((Kind GlobalVariableWrite)));foreach($name in @('NumberValue','TextValue','BooleanValue','ResultCodeValue')){Assert($null-ne($readPorts|Where-Object{$_.PortName-eq$name}))('Missing read port '+$name);Assert($null-ne($writePorts|Where-Object{$_.PortName-eq$name}))('Missing write port '+$name)}

  M 'LoadDockConfigurationDraft' ([object[]]@($readNumber))|Out-Null;Assert((F 'DockGlobalVariablePanel').Visibility.ToString()-eq'Visible'-and(F 'DockGlobalVariableComboBox').SelectedValue-eq$number.VariableId) 'Contextual variable dock failed'
  $recipe=M 'CaptureRecipe';Assert($recipe.GlobalVariables.Count-eq4-and($recipe.GlobalVariables|Where-Object{$_.VariableId-eq$number.VariableId}).Count-eq1) 'Variable recipe capture failed'
  $serializer=[Runtime.Serialization.Json.DataContractJsonSerializer]::new($recipeType);$stream=New-Object IO.MemoryStream;try{$serializer.WriteObject($stream,$recipe);$stream.Position=0;$roundtrip=$serializer.ReadObject($stream)}finally{$stream.Dispose()};Assert($roundtrip.GlobalVariables.Count-eq4-and$roundtrip.GlobalVariables[0].VariableId.Length-gt0) 'Variable recipe JSON roundtrip failed'
  $oldSerializer=[Runtime.Serialization.Json.DataContractJsonSerializer]::new($recipeType);$bytes=[Text.Encoding]::UTF8.GetBytes('{}');$oldStream=New-Object IO.MemoryStream(,$bytes);try{$old=$oldSerializer.ReadObject($oldStream)}finally{$oldStream.Dispose()};M 'LoadGlobalVariablesFromRecipe' ([object[]]@($old))|Out-Null;Assert($globals.Count-eq0) 'Old recipe without GlobalVariables did not load as an empty collection'
  Write-Output 'S59 global variable workbench + Number/String/Boolean/ResultCode read/write/downstream/failure/recipe/undo lifecycle passed; single-solution deterministic scope only'
}finally{$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if($ownsApp){$app.Shutdown()};if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
